-- ============================================================
-- [ahbot] 做市商受管市场 全静态整合版 (2026-09-07d)
-- book 完全由本文件 category=1 行决定(代码零类别判断)。
-- 当前 book=118 项(运营定制): 布6(亚麻/毛/丝绸/魔纹/符文/灵纹) +
-- 皮6(轻中重厚硬甲结缔) + 矿 + 草40(旧世界28+外域12: 血蓟/魔草/
-- 梦露花/魔花/火焰帽/泰罗果/远古苔/虚空花/噩梦藤/法力蓟/魔莲花/噩梦种子)
-- + 元素23 + 附魔30; + cat3 禁售48。全静态幂等; 服务器只 UPDATE。
-- 品质 target: 白20组=stack*80 绿10组=stack*40 蓝/紫5组=stack*20;
-- target=组数x堆叠x4, capacity=3xtarget, qty=target
-- ============================================================
USE tbccharacters;

CREATE TABLE IF NOT EXISTS `ahbot_market_state` (
  `item` INT UNSIGNED NOT NULL,
  `auction_house` TINYINT UNSIGNED NOT NULL DEFAULT 0,
  `enabled` TINYINT UNSIGNED NOT NULL DEFAULT 1,
  `category` TINYINT UNSIGNED NOT NULL DEFAULT 1 COMMENT '0=loot,1=market,2=fixed,3=ban',
  `price` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'category=2 固定价',
  `target` INT UNSIGNED NOT NULL DEFAULT 500,
  `capacity` INT UNSIGNED NOT NULL DEFAULT 1500,
  `qty` INT UNSIGNED NOT NULL DEFAULT 0,
  `avg_cost` INT UNSIGNED NOT NULL DEFAULT 0,
  `spent` INT UNSIGNED NOT NULL DEFAULT 0,
  `earned` INT UNSIGNED NOT NULL DEFAULT 0,
  `flow_bought` INT UNSIGNED NOT NULL DEFAULT 0,
  `flow_sold` INT UNSIGNED NOT NULL DEFAULT 0,
  `price_ref` INT UNSIGNED NOT NULL DEFAULT 0,
  `override_base_price` INT UNSIGNED NOT NULL DEFAULT 0,
  `override_add_chance` TINYINT UNSIGNED NOT NULL DEFAULT 0,
  `override_min_amount` INT UNSIGNED NOT NULL DEFAULT 0,
  `override_max_amount` INT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`item`, `auction_house`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='ahbot market-maker state (唯一配置源)';

-- 1) 做市统一 house2
DELETE FROM ahbot_market_state WHERE auction_house <> 2;

-- 2) 非受管行删除(仅 cat 0/1/2; cat3 禁售保留)
DELETE FROM ahbot_market_state WHERE category IN (0,1,2) AND item NOT IN (765, 785, 2318, 2319, 2447, 2449, 2450, 2452, 2453, 2589, 2592, 2770, 2771, 2772, 2835, 2836, 2838, 3356, 3357, 3358, 3818, 3819, 3820, 3821, 3857, 3858, 4234, 4304, 4306, 4338, 4625, 7067, 7068, 7069, 7070, 7075, 7076, 7077, 7078, 7079, 7080, 7081, 7082, 7911, 7912, 7972, 8153, 8170, 8831, 8836, 8838, 8839, 8845, 8846, 10286, 10938, 10939, 10940, 10978, 10998, 11082, 11083, 11084, 11134, 11135, 11137, 11138, 11139, 11174, 11175, 11176, 11177, 11178, 12803, 12808, 13463, 13464, 13465, 13466, 13467, 13468, 14047, 14343, 14344, 16202, 16203, 16204, 20725, 21877, 21887, 22445, 22446, 22447, 22449, 22450, 22572, 22573, 22574, 22575, 22576, 22577, 22578, 22710, 22785, 22786, 22787, 22788, 22789, 22790, 22791, 22792, 22793, 22794, 22797, 23424, 23425, 23426, 23427);

-- 2b) 只保留 category 1/3: 其它 category 行(遗留 cat0/cat2)一律删除
DELETE FROM ahbot_market_state WHERE category NOT IN (1,3);

-- 3) book 内非禁售统一 cat1
UPDATE ahbot_market_state SET enabled = 1, category = 1 WHERE auction_house = 2 AND item IN (765, 785, 2318, 2319, 2447, 2449, 2450, 2452, 2453, 2589, 2592, 2770, 2771, 2772, 2835, 2836, 2838, 3356, 3357, 3358, 3818, 3819, 3820, 3821, 3857, 3858, 4234, 4304, 4306, 4338, 4625, 7067, 7068, 7069, 7070, 7075, 7076, 7077, 7078, 7079, 7080, 7081, 7082, 7911, 7912, 7972, 8153, 8170, 8831, 8836, 8838, 8839, 8845, 8846, 10286, 10938, 10939, 10940, 10978, 10998, 11082, 11083, 11084, 11134, 11135, 11137, 11138, 11139, 11174, 11175, 11176, 11177, 11178, 12803, 12808, 13463, 13464, 13465, 13466, 13467, 13468, 14047, 14343, 14344, 16202, 16203, 16204, 20725, 21877, 21887, 22445, 22446, 22447, 22449, 22450, 22572, 22573, 22574, 22575, 22576, 22577, 22578, 22710, 22785, 22786, 22787, 22788, 22789, 22790, 22791, 22792, 22793, 22794, 22797, 23424, 23425, 23426, 23427) AND category <> 3;

-- 4) cat3 禁售行确保存在(48 项)

-- 5) book 行确保存在(118 项, qty=target)

